const staySearchRenderBase=render;
let staySearchCategory='All stays';
const searchIcons={hotel:'<path d="M5 28V6h17v22M9 10h2m4 0h2M9 15h2m4 0h2M9 20h2m4 0h2M11 28v-5h6v5M22 14h6v14M2 28h28"/>',home:'<path d="m3 15 13-11 13 11M7 12v16h18V12M13 28V18h6v10M11 12h3m4 0h3"/>',temple:'<path d="M5 28h22M8 28V17h16v11M5 17h22L16 6ZM16 6V2m0 0h7l-7 4M13 28v-7h6v7M7 31h18"/>',tent:'<path d="m2 28 14-23 14 23ZM16 5v23M9 28l7-12 7 12M12 5l4 3 4-3"/>',family:'<circle cx="11" cy="10" r="4"/><circle cx="24" cy="11" r="3"/><path d="M3 28v-7c0-7 16-7 16 0v7M21 18c5-2 10 1 10 5v5M8 28v-7m6 7v-7"/>',all:'<path d="M4 4h10v10H4ZM20 4h10v10H20ZM4 20h10v10H4ZM20 20h10v10H20Z"/>'};
function stayIcon(key){return `<svg viewBox="0 0 34 34" aria-hidden="true">${searchIcons[key]}</svg>`}
function dateVisual(value){const d=new Date(value+'T12:00:00');return `<strong>${d.getDate()}</strong><span>${d.toLocaleDateString('en-IN',{month:'short'})} '${String(d.getFullYear()).slice(2)}</span><small>${d.toLocaleDateString('en-IN',{weekday:'long'})}</small>`}
function selectStayCategory(value,button){staySearchCategory=value;document.querySelectorAll('.stay-service').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');if(value==='Group stays')toast('For groups larger than four rooms, use the group enquiry option below.')}
function staySearchMarkup(){return `<div class="stay-services" role="group" aria-label="Choose your accommodation">${[['all','All stays'],['hotel','Budget Hotels'],['hotel','Premium Hotels & Resorts'],['home','Homestays'],['temple','Dharamshalas'],['tent','Tent Cities'],['family','Group stays']].map(([icon,value])=>`<button class="stay-service ${staySearchCategory===value?'active':''}" aria-pressed="${staySearchCategory===value}" onclick="selectStayCategory('${value}',this)">${stayIcon(icon)}<span>${{'Budget Hotels':'Hotels','Premium Hotels & Resorts':'Hotels & Resorts','Tent Cities':'Tent cities'}[value]||value}</span></button>`).join('')}</div><div class="stay-search-meta"><div><span class="stay-standard">✓ Up to 4 rooms</span><a href="#/support">○ Group enquiries <small>For larger groups</small></a></div><p>Find your stay for <strong>Nashik Kumbh 2027</strong> <span>·</span> <a href="#/list-property">List your property ↗</a></p></div><form class="stay-search-form" onsubmit="submitStaySearch(event)"><div class="stay-search-fields"><div class="stay-search-cell destination-cell"><label for="stay-destination">City, area or pilgrimage landmark</label><select name="destination" id="stay-destination">${['All destinations',...locations].map(l=>`<option ${state.destination===l?'selected':''}>${l==='All destinations'?'Nashik & Trimbak':l}</option>`).join('')}</select><small>Maharashtra, India</small></div><div class="stay-search-cell date-cell"><label for="stay-in">Check-in <span>⌄</span></label><div id="stay-in-visual" class="date-visual">${dateVisual(state.checkin)}</div><input id="stay-in" name="checkin" type="date" value="${state.checkin}" required aria-label="Check-in date" onchange="document.getElementById('stay-in-visual').innerHTML=dateVisual(this.value)"></div><div class="stay-search-cell date-cell"><label for="stay-out">Check-out <span>⌄</span></label><div id="stay-out-visual" class="date-visual">${dateVisual(state.checkout)}</div><input id="stay-out" name="checkout" type="date" value="${state.checkout}" required aria-label="Check-out date" onchange="document.getElementById('stay-out-visual').innerHTML=dateVisual(this.value)"></div><div class="stay-search-cell party-cell"><label for="stay-rooms">Rooms & guests <span>⌄</span></label><div><select name="rooms" id="stay-rooms" aria-label="Number of rooms">${[1,2,3,4].map(n=>`<option value="${n}" ${state.rooms===n?'selected':''}>${n} room${n>1?'s':''}</option>`).join('')}</select><select name="guests" aria-label="Number of guests">${[1,2,3,4,5,6,8].map(n=>`<option value="${n}" ${state.guests===n?'selected':''}>${n} guest${n>1?'s':''}</option>`).join('')}</select></div><small>Travelling together, staying comfortably</small></div><div class="stay-search-cell budget-cell"><label for="stay-budget">Price per night</label><select id="stay-budget" name="budget">${[[10000,'Any budget'],[1500,'Up to ₹1,500'],[2500,'Up to ₹2,500'],[5000,'Up to ₹5,000']].map(([v,t])=>`<option value="${v}" ${state.max===v?'selected':''}>${t}</option>`).join('')}</select><small>Sample room rates, before tax</small></div></div><div class="stay-trending"><span>Popular searches:</span>${['Nashik City','Trimbakeshwar','Panchavati / Ramkund'].map(l=>`<button type="button" onclick="document.getElementById('stay-destination').value='${l}'">${l==='Panchavati / Ramkund'?'Near Ramkund':l}</button>`).join('')}</div><button class="stay-search-submit" type="submit">SEARCH STAYS <span>→</span></button></form>`}
function submitStaySearch(e){e.preventDefault();if(staySearchCategory==='Group stays'){go('/support');return}const data=new FormData(e.target);if(data.get('checkout')<=data.get('checkin')){toast('Choose a check-out date after check-in.');return}state.type=staySearchCategory;state.max=+data.get('budget');searchSubmit(e)}
render=function(){staySearchRenderBase();const search=document.querySelector('.booking-search');if(search){search.classList.add('reference-search');search.innerHTML=staySearchMarkup();document.querySelector('.booking-hero')?.classList.add('reference-hero')}};render();
